<script setup lang="ts">
import {musicThemes} from "~/data/music"
const state=useAtelier(),audio=useAudio(),{t,language}=useLocale(),settings=ref(false)
const frameStats=useState('scene-performance',()=>({fps:0,renderMs:0,drawCalls:0,triangles:0,pixelRatio:0,visible:false}))
function toggleSound(){state.sound.value=!state.sound.value;audio.click()}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}
</script>
