 <header class="header"><NuxtLink to="/" class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></NuxtLink><nav><NuxtLink to="/">{{t('Обзор','Experience')}}</NuxtLink><NuxtLink to="/garage">{{t('Гараж','Garage')}} <sup>08</sup></NuxtLink><NuxtLink :to="'/drive/'+state.car.value.id">{{t('В движении','In motion')}}</NuxtLink></nav><div class="header-tools"><button class="language-button" :aria-label="language==='ru'?'Switch to English':'Перевести на русский'" @click="language=language==='ru'?'en':'ru'">{{language==='ru'?'EN':'RU'}}</button><button :aria-label="t('Настройки','Settings')" @click="settings=true">⚙</button><button :aria-label="t('Полный экран','Fullscreen')" @click="fullscreen">⛶</button></div></header>
 <AtelierDialog v-if="settings" @close="settings=false"><small>VELOCITY 3 / {{t('ПАРАМЕТРЫ','PREFERENCES')}}</small><h2>{{t('Настройки','Settings')}}</h2><section class="music-picker" aria-label="Музыкальные темы"><div class="music-heading"><strong>{{t('Музыка · выбрать трек','Music · choose a track')}}</strong><label>{{t('Включена','Enabled')}}<input type="checkbox" v-model="state.music.value"></label></div><div class="music-tracks"><button v-for="theme in musicThemes" :key="theme.id" :aria-pressed="state.musicTheme.value===theme.id||(state.musicTheme.value==='auto'&&theme.id===(state.car.value.shape===0?'pulse':'atelier'))" @click="state.musicTheme.value=theme.id;state.music.value=true"><span>♫</span><span class="track-label">{{theme.name}}<small>{{theme.genre}} · {{theme.artist}}</small></span><span class="track-check">✓</span></button></div><button class="music-auto" :aria-pressed="state.musicTheme.value==='auto'" @click="state.musicTheme.value='auto'">{{t('Подбирать тему по автомобилю','Match music to vehicle')}}</button><p class="music-credit">Neon, Machina, Chasing Daylight — <a href="https://www.scottbuckley.com.au/library/" target="_blank" rel="noopener">Scott Buckley</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a></p></section><label>{{t('Качество графики','Graphics quality')}}<select v-model="state.quality.value"><option v-for="(q,i) in ['Medium','High','Ultra']" :value="q">{{t(['Среднее','Высокое','Ультра'][i]!,q)}}</option></select></label><p v-if="frameStats.fps" class="frame-status">{{t('Плавность','Frame rate')}} · {{frameStats.fps}} FPS</p><label>{{t('Тени','Shadows')}}<input type="checkbox" v-model="state.shadows.value"></label><label>{{t('Анимация камеры','Camera animation')}}<input type="checkbox" v-model="state.motion.value"></label><label>{{t('Звуки интерфейса','Interface sounds')}}<input type="checkbox" v-model="state.sound.value" @change="audio.click()"></label><label>{{t('Громкость','Volume')}}<input type="range" min="0" max="1" step="0.01" v-model.number="state.volume.value" @change="audio.click()"></label><p>{{t('Музыка начинается после первого нажатия. Двигатель включается отдельно и звучит при движении. Качество графики меняет разрешение сцены и детализацию теней.','Music starts after your first interaction. Engine audio is enabled separately and plays while moving. Graphics quality changes render resolution and shadow detail.')}}</p></AtelierDialog>

